import com.google.auth.oauth2.GoogleCredentials;
import com.google.gson.*;
import java.net.*;import java.io.*;import java.nio.file.*;import java.nio.channels.FileChannel;import java.nio.ByteBuffer;import java.security.MessageDigest;import java.util.*;
/** Session-only exact-key cleanup. All live guards are read in the same read-write transaction. */
public final class DeleteExactOwnedSpannerGraph {
 static final String ROOT="projects/halo-cmm-dev/instances/dev-instance/databases/";
 static final Map<String,Set<String>> TABLES=Map.of(
  "edp-aggregator",Set.of("RawImpressionUpload","ImpressionMetadata","RequisitionMetadata","ReportRoutingDecision","RawImpressionUploadCorrectionCandidate","UploadHealingOperation","DataAvailabilitySyncLease","VidLabelingEvictionFenceMutation"),
  "secure-computation",Set.of("WorkItems"),
  "kingdom",Set.of("Measurements","DataProviderAvailabilityIntervals","EventGroups","ModelRollouts","ModelLines","ModelShards","ModelReleases"));
 static GoogleCredentials cred;
 static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
 static void check(boolean b,String m){if(!b)throw new IllegalStateException(m);}
 static JsonObject request(String path,String method,JsonObject body)throws Exception {
  cred.refreshIfExpired();var token=cred.getAccessToken();var conn=(HttpURLConnection)new URI("https://spanner.googleapis.com/v1/"+path).toURL().openConnection();conn.setRequestMethod(method);conn.setConnectTimeout(30000);conn.setReadTimeout(120000);conn.setRequestProperty("Authorization","Bearer "+token.getTokenValue());conn.setRequestProperty("Content-Type","application/json");
  try {if(body!=null){conn.setDoOutput(true);try(var os=conn.getOutputStream()){os.write(body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
  int code=conn.getResponseCode();String text;try(var input=code<400?conn.getInputStream():conn.getErrorStream()){text=new String(input.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}check(code>=200&&code<300,"Spanner HTTP "+code+": "+text);return text.isBlank()?new JsonObject():JsonParser.parseString(text).getAsJsonObject();}finally{conn.disconnect();}
 }
 static JsonObject obj(String key,String value){var o=new JsonObject();o.addProperty(key,value);return o;}
 static String canonicalRows(JsonArray rows){var r=new ArrayList<String>();for(var x:rows)r.add(x.toString());Collections.sort(r);return r.toString();}
 static void journal(Path path,JsonObject value)throws Exception {Files.createDirectories(path.getParent());var tmp=path.resolveSibling(path.getFileName()+".tmp");byte[] b=(value.toString()+"\n").getBytes(java.nio.charset.StandardCharsets.UTF_8);try(var f=FileChannel.open(tmp,StandardOpenOption.WRITE,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING)){var buffer=ByteBuffer.wrap(b);while(buffer.hasRemaining())f.write(buffer);f.force(true);}Files.move(tmp,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);try(var d=FileChannel.open(path.getParent(),StandardOpenOption.READ)){d.force(true);}}
 public static void main(String[] a)throws Exception {
  check(a.length==4,"manifest expectedSHA --dry-run|--execute journal");check(a[2].equals("--dry-run")||a[2].equals("--execute"),"explicit mode");byte[] bytes=Files.readAllBytes(Path.of(a[0]));check(sha(bytes).equals(a[1]),"manifest hash mismatch");var m=JsonParser.parseString(new String(bytes,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();check(m.get("project").getAsString().equals("halo-cmm-dev")&&m.get("session").getAsString().equals("01a1d445")&&m.get("kind").getAsString().equals("EXACT_OWNED_SPANNER_GRAPH"),"scope mismatch");String db=m.get("database").getAsString();check(TABLES.containsKey(db),"database forbidden");check(m.get("rawDoneReadableAbsent").getAsBoolean()&&m.get("mainRestoreVerified").getAsBoolean(),"cleanup barriers absent");var deletes=m.getAsJsonArray("deletes");Set<String> seen=new HashSet<>();
  for(var e:deletes){var d=e.getAsJsonObject();String table=d.get("table").getAsString();check(TABLES.get(db).contains(table)&&seen.add(table),"table forbidden/duplicate");int width=d.get("primaryKeyColumns").getAsJsonArray().size();check(width>0,"missing PK proof");Set<String> keys=new HashSet<>();for(var k:d.getAsJsonArray("keys")){check(k.isJsonArray()&&k.getAsJsonArray().size()==width&&keys.add(k.toString()),"duplicate or wrong-width key");for(var v:k.getAsJsonArray())check(v.isJsonPrimitive()&&v.getAsJsonPrimitive().isString()&&!v.getAsString().isBlank(),"key must preserve exact strings");}check(d.getAsJsonArray("keys").size()==d.get("expectedParentCount").getAsInt(),"key count mismatch");check(d.has("ownershipProofSha256")&&d.get("ownershipProofSha256").getAsString().length()==64,"missing ownership binding");}
  var guards=m.getAsJsonArray("guards");check(guards.size()>=deletes.size()+2,"missing live guard closure");for(var e:guards){var g=e.getAsJsonObject();check(g.get("sql").getAsString().stripLeading().toUpperCase().startsWith("SELECT ")&&g.has("expectedRows")&&g.has("expectedFields"),"guard must be exact read-only SELECT");}
  Path jp=Path.of(a[3]).toAbsolutePath().normalize();check(jp.startsWith(Path.of("/tmp/vid-cloud-data-01a1d445"))&&!Files.exists(jp)&&jp.getParent().toRealPath().startsWith(Path.of("/tmp/vid-cloud-data-01a1d445").toRealPath()),"unique real session journal required");var j=new JsonObject();j.addProperty("snapshotSha256",a[1]);j.addProperty("database",db);j.addProperty("mode",a[2]);j.addProperty("state","VALIDATED_NO_CONNECTION");journal(jp,j);cred=GoogleCredentials.getApplicationDefault().createScoped("https://www.googleapis.com/auth/cloud-platform");String session=null,txn=null;boolean commitAttempted=false,committed=false;
  try{session=request(ROOT+db+"/sessions","POST",new JsonObject()).get("name").getAsString();var body=new JsonObject();var options=new JsonObject();options.add("readWrite",new JsonObject());body.add("options",options);txn=request(session+":beginTransaction","POST",body).get("id").getAsString();int n=0;
   for(var e:guards){var g=e.getAsJsonObject();body=obj("sql",g.get("sql").getAsString());body.add("transaction",obj("id",txn));var actual=request(session+":executeSql","POST",body);var rows=actual.has("rows")?actual.getAsJsonArray("rows"):new JsonArray();var fields=actual.getAsJsonObject("metadata").getAsJsonObject("rowType").getAsJsonArray("fields");check(fields.equals(g.getAsJsonArray("expectedFields")),"guard schema changed "+g.get("label"));check(canonicalRows(rows).equals(canonicalRows(g.getAsJsonArray("expectedRows"))),"live guard changed "+g.get("label"));j.addProperty("guardsPassed",++n);journal(jp,j);}
   if(a[2].equals("--dry-run")){j.addProperty("state","DRY_RUN_LIVE_GUARDS_PASS");journal(jp,j);System.out.println(j);return;}
   var mutations=new JsonArray();for(var e:deletes){var d=e.getAsJsonObject();var del=obj("table",d.get("table").getAsString());var keyset=new JsonObject();keyset.add("keys",d.get("keys"));del.add("keySet",keyset);var mutation=new JsonObject();mutation.add("delete",del);mutations.add(mutation);}body=obj("transactionId",txn);body.add("mutations",mutations);j.addProperty("state","COMMIT_INTENT");j.add("mutations",mutations);journal(jp,j);commitAttempted=true;var result=request(session+":commit","POST",body);committed=true;j.addProperty("state","COMMITTED");j.add("commit",result);journal(jp,j);System.out.println(j);
  }catch(Exception e){j.addProperty("state",committed?"COMMITTED_JOURNAL_FAILURE_RECONCILE":commitAttempted?"COMMIT_UNCERTAIN_RECONCILE_DO_NOT_REPEAT":"FAILED_BEFORE_COMMIT");j.addProperty("error",e.getMessage());journal(jp,j);throw e;}
  finally{if(session!=null){if(txn!=null&&!committed&&!commitAttempted){try{request(session+":rollback","POST",obj("transactionId",txn));}catch(Exception ignored){}}request(session,"DELETE",null);}}
 }
}
